<template>
  <section class="management-work recovery-work"><div class="work-heading"><h2>Historial y respaldos</h2><button type="button" :disabled="loading" @click="load"><RefreshCw :size="18"/> Actualizar</button></div><div class="work-tabs" role="tablist" aria-label="Historial y respaldos"><button v-for="(label,key) in tabs" :key="key" type="button" role="tab" :aria-selected="tab===key" @click="tab=key">{{ label }}</button></div><p v-if="error" role="alert" class="work-error">{{ error }}</p><p v-if="message" role="status">{{ message }}</p><p v-if="loading" role="status">Cargando…</p>
    <template v-if="tab==='backups'"><p class="work-muted">Respaldo automático diario de datos e imágenes, verificado y conservado en este servidor. Guarda también una copia de los datos fuera del servidor; estos archivos contienen información privada.</p><button class="work-primary" type="button" :disabled="busy || backup.running" @click="create"><ShieldCheck :size="18"/> {{ backup.running ? 'Creando respaldo…' : 'Crear respaldo ahora' }}</button><p v-if="backup.error" class="work-error" role="alert">{{ backup.error }}</p><p v-if="!backup.backups?.length && !loading">Todavía no hay un respaldo completo.</p><article v-for="entry in backup.backups || []" :key="entry.id" class="recovery-row"><div><strong>{{ date(entry.created_at) }}</strong><p>{{ entry.verified ? 'Verificado' : 'Pendiente de verificación' }} · {{ entry.files }} archivos de imagen</p><small>Los datos se descargan en JSON comprimido. Las imágenes se conservan en la copia del servidor.</small></div><button type="button" :disabled="busy" @click="download(entry)"><Download :size="18"/> Descargar datos</button></article></template>
    <template v-if="tab==='content'"><p v-if="!versions.length && !loading">El historial comienza con tu próximo cambio de contenido.</p><article v-for="entry in versions" :key="entry.id" class="recovery-row"><div><strong>{{ date(entry.created_at) }}</strong><small>Contenido anterior a un guardado</small></div><div class="recovery-actions"><button type="button" :disabled="busy" @click="preview(entry)"><Eye :size="18"/> Ver versión</button><button type="button" :disabled="busy" @click="restore(entry)"><History :size="18"/> Restaurar contenido</button></div></article></template>
    <template v-if="tab==='activity'"><p v-if="!activity.length && !loading">Todavía no hay cambios registrados.</p><article v-for="entry in activity" :key="entry.id" class="recovery-row"><div><strong>{{ describe(entry) }}</strong><p>{{ entry.admin_name || 'Administrador' }} · {{ date(entry.created_at) }}</p><small>{{ entry.resource }}</small></div></article></template>
  </section>
</template>
<script setup>
import {onBeforeUnmount,onMounted,ref} from 'vue'
import {RefreshCw,ShieldCheck,Download,History,Eye} from 'lucide-vue-next'
import {managementApi} from '../../api/index.js'
import {openContentPreview} from '../../utils/contentPreview.js'
const emit=defineEmits(['restored']),props=defineProps({hasUnsaved:{type:Boolean,default:false}})
const tabs={backups:'Respaldos',content:'Versiones de contenido',activity:'Actividad'},tab=ref('backups'),loading=ref(false),busy=ref(false),error=ref(''),message=ref(''),backup=ref({backups:[]}),versions=ref([]),activity=ref([])
let poll
const date=value=>new Date(value).toLocaleString('es-CL')
const describe=row=>row.detail || ({POST:'Creación o acción',PUT:'Edición',PATCH:'Actualización',DELETE:'Desactivación',PRICE:'Cambio de precio'}[row.action] || row.action)
async function load(){loading.value=true;error.value='';try{const [b,v,a]=await Promise.all([managementApi.backups(),managementApi.revisions(),managementApi.activity()]);backup.value=b.data;versions.value=v.data;activity.value=a.data;if(backup.value.running&&!poll)poll=setInterval(refreshBackup,3000)}catch(e){error.value=e.response?.data?.error || 'No pudimos cargar el historial.'}finally{loading.value=false}}
async function refreshBackup(){try{backup.value=(await managementApi.backups()).data;if(!backup.value.running){clearInterval(poll);poll=null}}catch{clearInterval(poll);poll=null;error.value='No pudimos actualizar el estado del respaldo.'}}
async function create(){busy.value=true;error.value='';try{await managementApi.createBackup();await refreshBackup();if(backup.value.running&&!poll)poll=setInterval(refreshBackup,3000)}catch(e){error.value=e.response?.data?.error || 'No pudimos iniciar el respaldo.'}finally{busy.value=false}}
async function download(entry){busy.value=true;error.value='';try{const {data}=await managementApi.downloadBackup(entry.id);const url=URL.createObjectURL(data),a=document.createElement('a');a.href=url;a.download=`bloomskin-${entry.created_at.slice(0,10)}.json.gz`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){error.value='No pudimos descargar el respaldo.'}finally{busy.value=false}}
async function preview(entry){error.value='';const target=window.open('about:blank','_blank');if(!target){error.value='Permite abrir pestañas para previsualizar.';return}try{const {data}=await managementApi.revision(entry.id);openContentPreview(data,target)}catch{target.close();error.value='No pudimos abrir esa versión.'}}
async function restore(entry){if(props.hasUnsaved){error.value='Guarda o descarta tus cambios de contenido antes de restaurar una versión.';return}if(!window.confirm('¿Restaurar este contenido? Se guardará una copia de la versión actual. No se modifican pedidos ni inventario.'))return;busy.value=true;error.value='';try{const {data}=await managementApi.restoreRevision(entry.id);message.value='Contenido restaurado. Los pedidos y el inventario no cambiaron.';emit('restored',data.site);await load()}catch(e){error.value=e.response?.data?.error || 'No pudimos restaurar el contenido.'}finally{busy.value=false}}
onMounted(load);onBeforeUnmount(()=>clearInterval(poll))
</script>
<style scoped>
.recovery-row{display:flex;justify-content:space-between;gap:20px;align-items:center;padding:20px 0;border-bottom:1px solid var(--ad-border)}.recovery-row>div{min-width:0;overflow-wrap:anywhere}.recovery-row p{font-size:14px;margin:8px 0}.recovery-row small{display:block;color:var(--ad-muted);font-size:13px}.recovery-actions{display:flex;flex-wrap:wrap;gap:8px}@media(max-width:720px){.recovery-row{align-items:stretch;flex-direction:column}.recovery-actions>*{flex:1}}
</style>
